import * as THREE from 'three';
import './style.css';

// A self-contained, original, procedural 3D rugby match. No external models needed.
const mount = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#71979a');
scene.fog = new THREE.FogExp2('#71979a', 0.0085);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, 0.1, 180);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.16;
mount.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight('#d8efff', '#405a3c', 2.15));
const sun = new THREE.DirectionalLight('#fff0d6', 3.2); sun.position.set(-16, 24, 12); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -34; sun.shadow.camera.right = 34; sun.shadow.camera.top = 32; sun.shadow.camera.bottom = -32; sun.shadow.bias = -0.0004; scene.add(sun);
const fill = new THREE.DirectionalLight('#82c8ff', 1.3); fill.position.set(17, 9, -18); scene.add(fill);
const fieldMat = new THREE.MeshStandardMaterial({ color: '#427448', roughness: .95 });
const pitch = new THREE.Mesh(new THREE.PlaneGeometry(46, 118), fieldMat); pitch.rotation.x = -Math.PI / 2; pitch.position.y = -.08; pitch.receiveShadow = true; scene.add(pitch);
const outside = new THREE.Mesh(new THREE.PlaneGeometry(180, 190), new THREE.MeshStandardMaterial({ color: '#152d31', roughness: 1 })); outside.rotation.x = -Math.PI / 2; outside.position.y = -.22; scene.add(outside);
const lineMat = new THREE.MeshBasicMaterial({ color: '#f6f2dc', transparent: true, opacity: .78 });
function fieldLine(x, z, width, depth = .105, mat = lineMat) { const m = new THREE.Mesh(new THREE.BoxGeometry(width, .018, depth), mat); m.position.set(x, .012, z); scene.add(m); return m; }
for (const z of [-49, -40, -30, -20, -10, 0, 10, 20, 30, 40, 49]) fieldLine(0, z, z === -49 || z === 49 ? 38 : 46, z % 20 === 0 || Math.abs(z) === 49 ? .15 : .075);
for (const x of [-21, 21]) fieldLine(x, 0, .09, 100);
// Broken white five-metre dashes add the little visual detail of a real pitch.
for (const z of [-35, -25, -15, -5, 5, 15, 25, 35]) for (const x of [-17, -12, -7, 7, 12, 17]) fieldLine(x, z, .1, .7, new THREE.MeshBasicMaterial({ color: '#f6f2dc', transparent: true, opacity: .4 }));

// Stadium tiers, crowd silhouettes, giant floodlight trusses, and a late-day sky.
const crowdMats = ['#435058', '#e4dcc7', '#bb6b46', '#59788a', '#c4aa6b', '#a8b1a3', '#394752'].map(c => new THREE.MeshStandardMaterial({ color: c, roughness: .9 }));
for (let tier = 0; tier < 3; tier++) {
  const z = -64 - tier * 4.7, h = 3.2 + tier * .7;
  const stand = new THREE.Mesh(new THREE.BoxGeometry(86 + tier * 4, h, 5.7), new THREE.MeshStandardMaterial({ color: tier === 1 ? '#233941' : '#1a3039', roughness: .85 }));
  stand.position.set(0, h * .5 - .7, z); scene.add(stand);
  for (let row = 0; row < 7; row++) for (let i = 0; i < 90; i++) {
    const x = (i - 44.5) * 1.02 + (Math.random() - .5) * .22;
    const y = .4 + row * .4 + (Math.random() - .5) * .12;
    const group = new THREE.Group(); group.position.set(x, y, z + (Math.random() - .5) * 4.5);
    const jersey = crowdMats[Math.floor(Math.random() * crowdMats.length)];
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(.105, .21, 2, 4), jersey); body.position.y = .14; body.scale.set(1, 1.08, .68); group.add(body);
    const head = new THREE.Mesh(new THREE.SphereGeometry(.09, 6, 5), new THREE.MeshStandardMaterial({ color: Math.random() > .5 ? '#c28e68' : '#805c49', roughness: .9 })); head.position.y = .37; group.add(head); scene.add(group);
  }
}
for (const x of [-37, 37]) {
  const post = new THREE.Group(); post.position.set(x, 0, -49); scene.add(post);
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(.13, .2, 12, 8), new THREE.MeshStandardMaterial({ color: '#efeee3', metalness: .3, roughness: .42 })); pole.position.y = 6; post.add(pole);
  for (const dx of [-5, 5]) { const arm = new THREE.Mesh(new THREE.CylinderGeometry(.105, .105, 12, 8), pole.material); arm.position.set(dx / 2, 12, 0); arm.rotation.z = Math.PI / 2; post.add(arm); }
  const cross = new THREE.Mesh(new THREE.BoxGeometry(11, .13, .13), pole.material); cross.position.y = 12; post.add(cross);
}
for (const x of [-29, 29]) {
  const p = new THREE.Group(); p.position.set(x, 0, -28); scene.add(p);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(.14, .24, 14, 8), new THREE.MeshStandardMaterial({ color: '#445055', metalness: .55, roughness: .45 })); shaft.position.y = 7; p.add(shaft);
  const bar = new THREE.Mesh(new THREE.BoxGeometry(4.5, .45, .55), new THREE.MeshStandardMaterial({ color: '#dedbcf', emissive: '#b5c8ca', emissiveIntensity: .7 })); bar.position.y = 14; p.add(bar);
  for (let i = 0; i < 5; i++) { const bulb = new THREE.Mesh(new THREE.BoxGeometry(.52, .33, .18), new THREE.MeshBasicMaterial({ color: '#fff3d3' })); bulb.position.set(-1.6 + i * .8, 14, .32); p.add(bulb); }
}
// Brand boards around the pitch, subtle team identity.
for (const x of [-21.9, 21.9]) for (const z of [-34, -9, 17]) {
  const board = new THREE.Mesh(new THREE.BoxGeometry(.18, .9, 10), new THREE.MeshStandardMaterial({ color: z < 0 ? '#b7ea34' : '#45a6d7', emissive: z < 0 ? '#456c10' : '#12384d', emissiveIntensity: .35, roughness: .4 })); board.position.set(x, .48, z); scene.add(board);
}

const mat = (color, roughness = .68, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const skinTones = ['#cb9670', '#9c694d', '#e2b38a', '#714a38', '#b88062'];
const cloth = { home: mat('#1685b8', .63), away: mat('#d5a649', .64), trim: mat('#eaf3f1', .58), shorts: mat('#15232b', .82), boots: mat('#10191b', .48), sockBlue: mat('#39a6cc'), sockGold: mat('#eee0b9'), skin: skinTones.map(c => mat(c, .72)), hair: [mat('#201b18'), mat('#48342a'), mat('#342e2a'), mat('#a48152')], ball: mat('#a44730', .46), sole: mat('#c3af73', .55, .15) };
const sph = new THREE.SphereGeometry(1, 16, 12), limbGeo = new THREE.CapsuleGeometry(.105, .43, 4, 8);
function addMesh(parent, geometry, material, pos, scale, name) { const o = new THREE.Mesh(geometry, material); o.position.set(...pos); o.scale.set(...scale); if (name) o.name = name; o.castShadow = true; o.receiveShadow = true; parent.add(o); return o; }
function makePlayer(team, number, index = 0) {
  const root = new THREE.Group(); root.userData = { team, number, index };
  const jersey = team === 'home' ? cloth.home : cloth.away, socks = team === 'home' ? cloth.sockBlue : cloth.sockGold;
  const skin = cloth.skin[(number + 1) % cloth.skin.length], hair = cloth.hair[number % cloth.hair.length];
  const body = new THREE.Group(); body.position.y = .94; root.add(body); root.userData.body = body;
  addMesh(body, new THREE.CapsuleGeometry(.3, .47, 5, 10), jersey, [0, .03, 0], [1.12, 1.1, .83], 'torso');
  addMesh(body, new THREE.BoxGeometry(.48, .1, .035), cloth.trim, [0, .19, -.249], [1, 1, 1], 'chest stripe');
  const collar = addMesh(body, new THREE.TorusGeometry(.117, .027, 7, 14), cloth.trim, [0, .365, -.012], [1.06, .9, 1], 'collar'); collar.rotation.x = Math.PI / 2;
  const head = new THREE.Group(); head.position.set(0, .55, -.015); body.add(head); root.userData.head = head;
  addMesh(head, sph, skin, [0, .025, 0], [.21, .265, .2], 'face');
  addMesh(head, sph, hair, [0, .16, .025], [.22, .155, .205], 'hair');
  // Hair cap and unmistakable profile features.
  addMesh(head, sph, hair, [0, .115, -.13], [.195, .085, .085], 'hairline');
  for (const side of [-1, 1]) {
    addMesh(head, sph, skin, [side * .205, .02, 0], [.047, .07, .047], 'ear');
    const eye = addMesh(head, sph, mat('#f4e9d8', .48), [side * .081, .045, -.177], [.032, .027, .015], 'eye white');
    addMesh(head, sph, mat('#32251f', .42), [side * .081, .044, -.19], [.013, .018, .009], 'pupil');
    addMesh(head, sph, hair, [side * .08, .085, -.182], [.043, .014, .012], 'brow');
  }
  addMesh(head, sph, skin, [0, -.014, -.184], [.03, .04, .025], 'nose');
  addMesh(head, new THREE.BoxGeometry(.085, .012, .012), mat('#56352e'), [0, -.09, -.185], [1, 1, 1], 'mouth');
  const shorts = addMesh(body, new THREE.CapsuleGeometry(.23, .16, 4, 8), cloth.shorts, [0, -.36, .01], [1.28, .9, .88], 'shorts');
  // Raised shirt number on the back of the model.
  const numCanvas = document.createElement('canvas'); numCanvas.width = 128; numCanvas.height = 128;
  const ctx = numCanvas.getContext('2d'); ctx.fillStyle = '#fff'; ctx.font = '800 90px Arial'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(String(number).padStart(2, '0'), 64, 65);
  const numTex = new THREE.CanvasTexture(numCanvas); numTex.colorSpace = THREE.SRGBColorSpace;
  const num = new THREE.Mesh(new THREE.PlaneGeometry(.27, .33), new THREE.MeshBasicMaterial({ map: numTex, transparent: true, depthWrite: false })); num.position.set(0, .12, .266); num.rotation.y = Math.PI; body.add(num);
  const arms = [], legs = [];
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group(); shoulder.position.set(side * .31, .29, 0); body.add(shoulder); root.userData['arm' + (side < 0 ? 'L' : 'R')] = shoulder;
    addMesh(shoulder, limbGeo, jersey, [0, -.24, 0], [.85, 1.05, .86], 'upper arm');
    const elbow = new THREE.Group(); elbow.position.y = -.45; shoulder.add(elbow); addMesh(elbow, limbGeo, skin, [0, -.22, -.01], [.69, .88, .7], 'forearm');
    addMesh(elbow, sph, skin, [0, -.47, -.03], [.11, .092, .125], 'hand'); arms.push(shoulder);
    const hip = new THREE.Group(); hip.position.set(side * .15, -.48, .01); body.add(hip); root.userData['leg' + (side < 0 ? 'L' : 'R')] = hip;
    addMesh(hip, limbGeo, cloth.shorts, [0, -.235, 0], [1.05, 1.12, 1], 'thigh');
    const knee = new THREE.Group(); knee.position.y = -.43; hip.add(knee); addMesh(knee, limbGeo, socks, [0, -.24, 0], [.73, 1.08, .75], 'sock');
    addMesh(knee, new THREE.CapsuleGeometry(.11, .17, 3, 7), cloth.boots, [0, -.51, -.085], [1.22, .64, 1.7], 'boot');
    // Visible molded boot studs.
    for (const dx of [-.055, .045]) addMesh(knee, new THREE.ConeGeometry(.023, .06, 5), cloth.sole, [dx, -.585, -.06], [1, 1, 1], 'stud');
    root.userData['knee' + (side < 0 ? 'L' : 'R')] = knee;
    legs.push(hip);
  }
  root.userData.jersey = jersey; root.userData.pose = Math.random() * Math.PI * 2; root.userData.tackleFlash = 0;
  return root;
}

const actors = [];
const player = makePlayer('home', 7); player.position.set(0, 0, 8); scene.add(player); player.userData.controlled = true; actors.push(player);
const homeTeam = [player];
for (let i = 0; i < 4; i++) { const a = makePlayer('home', [3, 5, 9, 12][i], i + 1); a.position.set((i % 2 ? 1 : -1) * (4.6 + (i % 3) * .45), 0, 5 - Math.floor(i / 2) * 7); a.userData.formation = i; scene.add(a); actors.push(a); homeTeam.push(a); }
const defenders = [];
for (let i = 0; i < 6; i++) { const a = makePlayer('away', [2, 4, 6, 8, 10, 13][i], i); a.position.set((i - 2.5) * 3.7, 0, -16 + Math.abs(i - 2.5) * .65); a.userData.formation = i; scene.add(a); actors.push(a); defenders.push(a); }

const ball = new THREE.Group();
const ballBody = new THREE.Mesh(new THREE.SphereGeometry(.21, 20, 14), cloth.ball); ballBody.scale.set(.83, .78, 1.32); ball.add(ballBody);
const ballSeam = new THREE.Mesh(new THREE.TorusGeometry(.146, .009, 5, 30), mat('#e5d6b3', .62)); ballSeam.rotation.y = Math.PI / 2; ballSeam.scale.set(.84, .82, 1.28); ball.add(ballSeam);
for (let s = -1; s <= 1; s += 2) { const lace = new THREE.Mesh(new THREE.BoxGeometry(.012, .12, .018), mat('#eadbbc')); lace.position.set(0, .03, s * .075); ball.add(lace); }
scene.add(ball);

// Ball-carrier hand attachment, with independent ball motion during a pickup.
const clock = new THREE.Clock();
const game = { started: false, mode: 'attack', seconds: 240, home: 0, away: 0, stamina: 100, power: 100, active: player, ballCarrier: player, holding: {}, joystick: { x: 0, y: 0 }, replay: false, replayTimer: 0, replayKind: '', replaySeen: 0, scoreCooldown: 0, phaseCooldown: 0, toastTimer: 0, bannerTimer: 0, actionCooldown: 0, touchActive: false, ended: false, speed: 1, lastAttacker: null };
const el = id => document.getElementById(id);
const ui = { clock: el('clock'), home: el('home-score'), away: el('away-score'), stamina: el('stamina-fill'), power: el('power-fill'), staminaNum: el('stamina-number'), powerNum: el('power-number'), distance: el('distance'), possession: el('possession-label'), phaseLabel: el('phase-label'), banner: el('phase-banner'), bannerTitle: el('banner-title'), bannerSub: el('banner-subtitle'), toast: el('event-toast'), replay: el('replay-screen'), replayTitle: el('replay-title'), replaySub: el('replay-sub'), start: el('start-screen'), result: el('result-screen'), joyKnob: el('joy-knob') };
function banner(title, subtitle, seconds = 2.4) { ui.bannerTitle.textContent = title; ui.bannerSub.textContent = subtitle; ui.banner.classList.add('visible'); game.bannerTimer = seconds; }
function toast(text, seconds = 1.25) { ui.toast.textContent = text; ui.toast.classList.add('show'); game.toastTimer = seconds; }
function setCarrier(actor) { game.ballCarrier = actor; actor.userData.hasBall = true; for (const a of actors) if (a !== actor) a.userData.hasBall = false; }
function syncScore() { ui.home.textContent = String(game.home).padStart(2, '0'); ui.away.textContent = String(game.away).padStart(2, '0'); }
function updateHUD() {
  ui.stamina.style.width = `${game.stamina}%`; ui.power.style.width = `${game.power}%`;
  ui.staminaNum.textContent = Math.round(game.stamina); ui.powerNum.textContent = Math.round(game.power);
  ui.stamina.style.filter = game.stamina < 25 ? 'hue-rotate(-48deg) saturate(1.7)' : '';
  const meters = game.mode === 'attack' ? Math.max(0, Math.ceil(game.ballCarrier.position.z + 50)) : Math.max(0, Math.ceil(50 - game.ballCarrier.position.z));
  ui.distance.innerHTML = `${meters}<span>m</span>`;
  ui.possession.textContent = game.mode === 'attack' ? 'HARBOR IN POSSESSION' : 'IRONWOOD IN POSSESSION';
  ui.phaseLabel.textContent = game.seconds > 120 ? 'FIRST HALF' : 'SECOND HALF';
  ui.clock.textContent = `${String(Math.floor(game.seconds / 60)).padStart(2, '0')}:${String(Math.floor(game.seconds % 60)).padStart(2, '0')}`;
}
function ballLocal() { const arm = game.ballCarrier.userData.armR; return arm ? arm.localToWorld(new THREE.Vector3(.08, -.5, -.11)) : game.ballCarrier.position.clone().add(new THREE.Vector3(.25, .92, 0)); }
function beginGame() { if (game.started && !game.ended) return; game.started = true; game.ended = false; game.seconds = 240; game.home = 0; game.away = 0; game.mode = 'attack'; game.stamina = 100; game.power = 100; game.replaySeen = 0; ui.start.classList.add('hidden'); ui.result.classList.add('hidden'); placeReset(); banner('TAKE IT TO THE LINE', 'Find a gap. Make it count.', 3); }
el('start-button').addEventListener('click', beginGame); el('again-button').addEventListener('click', beginGame);
function placeReset() {
  for (const a of homeTeam) { a.rotation.set(0, 0, 0); a.visible = true; a.userData.fallen = false; a.userData.stun = 0; a.userData.pose = Math.random() * 5; }
  for (const a of defenders) { a.rotation.set(0, 0, 0); a.visible = true; a.userData.fallen = false; a.userData.stun = 0; }
  if (game.mode === 'attack') { player.position.set(0, 0, 8); setCarrier(player); defenders.forEach((a, i) => { a.position.set((i - 2.5) * 3.7, 0, -16 + Math.abs(i - 2.5) * .55); }); }
  else { player.position.set(0, 0, -28); const carrier = defenders[1]; carrier.position.set(0, 0, -17); setCarrier(carrier); homeTeam.slice(1).forEach((a, i) => a.position.set((i - 1.5) * 4, 0, -8 + i * 1.6)); }
  game.active = player; game.stamina = Math.max(65, game.stamina); game.power = 100; game.ballCarrier.userData.tackleFlash = 0;
}

function startReplay(kind) {
  if (game.replay || game.replaySeen >= 5 || game.ended) return;
  game.replay = true; game.replayKind = kind; game.replayTimer = 2.6; game.replaySeen++;
  ui.replayTitle.textContent = kind === 'TRY!' ? 'WHAT A FINISH.' : kind === 'ILLEGAL' ? 'PENALTY.' : kind === 'CHARGE' ? 'BIG CHARGE.' : 'WHAT A HIT.';
  ui.replaySub.textContent = kind === 'TRY!' ? 'HARBOR CITY OVER THE LINE.' : kind === 'ILLEGAL' ? 'HIGH CONTACT. PLAY TO THE WHISTLE.' : 'THE CROWD FELT THAT ONE.';
  ui.replay.classList.add('active'); ui.replay.setAttribute('aria-hidden', 'false'); ui.replay.classList.toggle('xray', kind !== 'TRY!');
  renderer.toneMappingExposure = 1.35;
}
function stopReplay() { game.replay = false; game.replayTimer = 0; ui.replay.classList.remove('active', 'xray'); ui.replay.setAttribute('aria-hidden', 'true'); renderer.toneMappingExposure = 1.16; }
el('replay-skip').addEventListener('click', stopReplay);

function changePossession(reason = 'TACKLED') {
  if (game.phaseCooldown > 0) return;
  game.phaseCooldown = 2.6; game.mode = game.mode === 'attack' ? 'defend' : 'attack';
  if (game.mode === 'defend') { game.away = game.away; banner('YOUR TURN TO TACKLE', 'Read the runner. Stop the break.', 2.6); toast(reason === 'PENALTY' ? 'PENALTY! POSSESSION LOST' : 'TURNOVER! GET BACK', 1.5); }
  else { banner('WIN IT BACK', 'Make the hit. Take it back.', 2.5); toast('HARBOR CITY BALL', 1.5); }
