// Fine performance details: subtle turf texture marks, stamina-dependent boot trails, and X-ray impact tracing.
const xrayMaterial = new THREE.LineBasicMaterial({ color: '#94f5ff', transparent: true, opacity: .9, depthTest: false });
let xrayLines = null;
