}
for (const z of [-49, -40, -30, -20, -10, 0, 10, 20, 30, 40, 49]) fieldLine(0, z, 42, z === 0 ? .22 : .11);
for (const x of [-21, 21]) fieldLine(x, 0, .14, 100);
