const parent=await p.locator('#mobile-controls').boundingBox();const buttons=await p.locator('#mobile-controls .action-button').evaluateAll(es=>es.map(e=>{const r=e.getBoundingClientRect();return {action:e.dataset.action,x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}}));const overflow=await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
await p.locator('[data-action="replay"]').tap();const toast=await p.locator('#event-toast').innerText();await p.waitForTimeout(900);
const joy=await p.locator('.joy-ring').boundingBox(),sprint=await p.locator('[data-action="sprint"]').boundingBox(),cdp=await c.newCDPSession(p);
await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:joy.x+joy.width/2,y:joy.y+joy.height/2,id:1},{x:sprint.x+sprint.width/2,y:sprint.y+sprint.height/2,id:2}]});
await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:joy.x+joy.width/2,y:joy.y+joy.height/2-30,id:1},{x:sprint.x+sprint.width/2,y:sprint.y+sprint.height/2,id:2}]});await new Promise(r=>setTimeout(r,900));await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
console.log(JSON.stringify({parent,buttons,overflow,replayToast:toast,staminaAfterMoveSprint:await p.locator('#stamina-number').innerText(),errors},null,2));await b.close();
